public boolean canArrange(int[] arr, int k) {
    Map<Integer, Integer> remainderCounts = new HashMap<>();

    for (int num : arr) {
        int remainder = (num % k + k) % k;
        remainderCounts.put(remainder, remainderCounts.getOrDefault(remainder, 0) + 1);
    }

    if (remainderCounts.getOrDefault(0, 0) % 2 != 0) {
        return false;
    }

    for (int i = 1; i <= k / 2; i++) {
        if (!remainderCounts.getOrDefault(i, 0).equals(remainderCounts.getOrDefault(k - i, 0))) {
            return false;
        }
    }

    return true;
}

