    for (int[] edge : edges) {
        adj.get(edge[0]).add(edge[1]);
        adj.get(edge[1]).add(edge[0]);
    }

    // Helper function to perform DFS and calculate the minimum time
    int[] result = new int[1];
    dfs(0, -1, hasApple, adj, result);
    return result[0] * 2;
}

