public int findMinFibonacciNumbers(int k) {
    // Generate Fibonacci numbers up to k
    List<Integer> fibs = new ArrayList<>();
    fibs.add(1);
    fibs.add(1);
    while (fibs.get(fibs.size() - 1) + fibs.get(fibs.size() - 2) <= k) {
        fibs.add(fibs.get(fibs.size() - 1) + fibs.get(fibs.size() - 2));
    }

    // Use a greedy algorithm to find the minimum number of Fibonacci numbers that sum up to k
    int count = 0;
    for (int i = fibs.size() - 1; i >= 0; i--) {
        while (k >= fibs.get(i)) {
            k -= fibs.get(i);
            count++;
        }
        if (k == 0) {
            break;
        }
    }

    return count;
}

