        num /= 10;
        while (num > 0) {
            int currentDigit = num % 10;
            if (Math.abs(currentDigit - prevDigit) != 1) return false;
            prevDigit = currentDigit;
            num /= 10;
        }
        return true;
    }
    // Iterate through the range and collect stepping numbers
    for (int i = low; i <= high; i++) {
        if (isSteppingNumber(i)) {
            result.add(i);
        }
    }
    return result;
}

