public static List<Integer> findSteppingNumbers(int low, int high) {
        List<Integer> result = new ArrayList<>();
        if (low <= 9) {
            for (int i = low; i <= Math.min(9, high); i++) {
                result.add(i);
            }
        }
        LinkedList<Integer> queue = new LinkedList<>();
        for (int i = 10; i <= 99; i++) {
            if (isSteppingNumber(i)) {
                result.add(i);
                queue.add(i);
            }
        }
        while (!queue.isEmpty()) {
            int current = queue.poll();
            int lastDigit = current % 10;
            if (lastDigit != 0) {
                int next = current * 10 + (lastDigit - 1);
                if (next <= high) {
                    result.add(next);
                    queue.add(next);
                }
            }
            if (lastDigit != 9) {
                int next = current * 10 + (lastDigit + 1);
                if (next <= high) {
                    result.add(next);
                    queue.add(next);
                }
            }
        }
        result.sort(Integer::compareTo);
        return result.stream().filter(n -> n >= low).collect(Collectors.toList());
    }

