public static List<String> centerSymmetricNumbers(int n) {
        List<String> result = new LinkedList<>();
        if (n == 1) {
            result.add("0");
            result.add("1");
            result.add("8");
            return result;
        }
        if (n > 1) {
            result.add("11");
            result.add("69");
            result.add("88");
            result.add("96");
        }

        Queue<String> queue = new LinkedList<>(result);
        int currentLength = 2;
        while (currentLength < n) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                String num = queue.poll();
                if (currentLength + 1 <= n) {
                    queue.offer("6" + num + "9");
                    queue.offer("9" + num + "6");
                }
                if (currentLength + 2 <= n) {
                    queue.offer("8" + num + "8");
                    if (currentLength + 2 < n) {
                        queue.offer("1" + num + "1");
                    }
                }
            }
            currentLength += 2;
        }

        return new LinkedList<>(result);
    }

